<?php require_once __DIR__.'/../../config/config.php'; require_once __DIR__.'/../../helpers/security.php'; require_once __DIR__.'/../../middleware/AdminMiddleware.php'; AdminMiddleware::handle(); $csrf=generateCsrfToken(); ?>
<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Member Management | IRONCORE</title><link rel="stylesheet" href="/assets/css/style.css"><link rel="stylesheet" href="/assets/css/dashboard.css"><link rel="stylesheet" href="/assets/css/responsive.css"><style>.toolbar{display:flex;gap:12px;flex-wrap:wrap;margin-bottom:18px}.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(190px,1fr));gap:14px;margin-bottom:18px}.stat{padding:18px}.stat b{display:block;font-size:28px;margin-top:6px}.form{display:grid;grid-template-columns:repeat(auto-fit,minmax(180px,1fr));gap:12px;margin-bottom:18px}.form input,.form select{width:100%;padding:10px;background:var(--color-bg);border:1px solid rgba(255,255,255,.12);color:inherit;border-radius:6px}.table{width:100%;border-collapse:collapse}.table th,.table td{padding:11px;border-bottom:1px solid rgba(255,255,255,.08);text-align:left}</style></head><body style="background:var(--color-bg)"><div class="dashboard-shell"><aside class="sidebar"><div class="sidebar-brand"><a href="/index.php" class="brand-logo"><span>IRONCORE</span></a><span class="sidebar-badge">ADMINISTRATOR CONTROL</span></div><ul class="sidebar-nav"><li><a href="/admin/index.php" class="nav-item-link">Dashboard</a></li><li><a href="/admin/members.php" class="nav-item-link active">Members</a></li><li><a href="/admin/trainers.php" class="nav-item-link">Trainers</a></li><li><a href="/admin/memberships.php" class="nav-item-link">Memberships</a></li><li><a href="/admin/attendance.php" class="nav-item-link">Attendance</a></li><li><a href="/admin/payments.php" class="nav-item-link">Payments</a></li><li><a href="/admin/workouts.php" class="nav-item-link">Workouts</a></li><li><a href="/admin/reports.php" class="nav-item-link">Reports</a></li></ul><div class="sidebar-footer"><a href="/logout.php" class="btn btn-primary" style="width:100%;justify-content:center">Logout</a></div></aside><div class="main-wrapper"><header class="dashboard-header"><div><h1>MEMBER MANAGEMENT</h1><p>Live member records, status and subscription information.</p></div></header><main class="dashboard-body"><div class="toolbar"><input id="q" class="form-control" placeholder="Search name, email or phone" style="max-width:330px"><button class="btn btn-secondary" onclick="load()">Refresh</button><button class="btn btn-primary" onclick="toggleForm()">+ Add Member</button></div><form id="form" class="form" style="display:none"><input type="hidden" name="csrf_token" value="<?=e($csrf)?>"><label>Name<input name="name" required></label><label>Email<input type="email" name="email" required></label><label>Phone<input name="phone"></label><label>Password<input type="password" name="password" placeholder="Member@123"></label><label>Join date<input type="date" name="join_date" value="<?=date('Y-m-d')?>"></label><button class="btn btn-primary" type="submit">Create Member</button></form><div id="stats" class="grid"></div><section class="panel-card" style="overflow:auto"><table class="table"><thead><tr><th>Name</th><th>Email</th><th>Phone</th><th>Plan</th><th>Expiry</th><th>Status</th></tr></thead><tbody id="body"></tbody></table></section></main></div></div><script>const api='/api.php';async function load(){let q=document.getElementById('q').value;let r=await fetch(api+'?action=members&q='+encodeURIComponent(q));let j=await r.json();if(!j.success){alert(j.message);return}let d=j.data||[];document.getElementById('body').innerHTML=d.map(x=>`<tr><td>${esc(x.full_name)}</td><td>${esc(x.email)}</td><td>${esc(x.phone||'')}</td><td>${esc(x.plan_title||'No plan')}</td><td>${esc(x.end_date||'')}</td><td>${esc(x.status)}</td></tr>`).join('')||'<tr><td colspan="6">No members found.</td></tr>';document.getElementById('stats').innerHTML=`<div class="panel-card stat"><span>Total Members</span><b>${d.length}</b></div><div class="panel-card stat"><span>Active</span><b>${d.filter(x=>x.status==='active').length}</b></div><div class="panel-card stat"><span>With Plans</span><b>${d.filter(x=>x.plan_title).length}</b></div>`}function esc(v){return String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}function toggleForm(){let f=document.getElementById('form');f.style.display=f.style.display==='none'?'grid':'none'}document.getElementById('q').oninput=()=>{clearTimeout(window.t);window.t=setTimeout(load,250)};document.getElementById('form').onsubmit=async e=>{e.preventDefault();let r=await fetch(api+'?action=create_member',{method:'POST',body:new FormData(e.target)});let j=await r.json();alert(j.message);if(j.success){e.target.reset();toggleForm();load()}};load();</script></body></html>